use std::path::Path;
use std::process::{Command, Output};

use httpmock::prelude::*;
use prost::Message;

/// The protocol messages, generated by the build script from the server's schema.
mod proto {
    include!(concat!(env!("OUT_DIR"), "/dandelion_frontend.rs"));
}

/// Builds a protocol body by hand, independently of the CLI's encoder.
fn envelope(metadata: &impl Message, payload: &[u8]) -> Vec<u8> {
    let mut body = Vec::new();
    prost::encoding::encode_varint(1, &mut body);
    body.extend(metadata.encode_length_delimited_to_vec());
    body.extend_from_slice(payload);
    body
}

fn status(message: &str) -> Vec<u8> {
    envelope(
        &proto::StatusResponse {
            message: message.into(),
        },
        &[],
    )
}

fn data_item(identifier: &str, key: u32, payload_length: u64) -> proto::DataItem {
    proto::DataItem {
        identifier: identifier.into(),
        key,
        payload_length,
    }
}

/// Runs `dandelion` with an isolated config file and no DANDELION_* environment.
fn run(config: &Path, args: &[&str]) -> Output {
    run_with_stdin(config, args, None)
}

fn run_with_stdin(config: &Path, args: &[&str], stdin: Option<&str>) -> Output {
    use std::io::Write;
    let mut cmd = Command::new(env!("CARGO_BIN_EXE_dandelion"));
    cmd.args(args)
        .env("DANDELION_CONFIG", config)
        .env_remove("DANDELION_URL")
        .stdin(std::process::Stdio::piped())
        .stdout(std::process::Stdio::piped())
        .stderr(std::process::Stdio::piped());
    let mut child = cmd.spawn().unwrap();
    {
        let mut pipe = child.stdin.take().unwrap();
        if let Some(s) = stdin {
            pipe.write_all(s.as_bytes()).unwrap();
        }
    }
    child.wait_with_output().unwrap()
}

fn stdout(o: &Output) -> String {
    String::from_utf8_lossy(&o.stdout).into_owned()
}
fn stderr(o: &Output) -> String {
    String::from_utf8_lossy(&o.stderr).into_owned()
}

/// A mock that only matches the exact body.
fn expect_body<'a>(
    server: &'a MockServer,
    path: &str,
    expected: Vec<u8>,
    status: u16,
    body: Vec<u8>,
) -> httpmock::Mock<'a> {
    server.mock(move |when, then| {
        when.method(POST)
            .path(path)
            .is_true(move |req| req.body_ref() == expected.as_slice());
        then.status(status).body(body);
    })
}

#[test]
fn register_function_with_flags() {
    let dir = tempfile::tempdir().unwrap();
    let cfg = dir.path().join("config.toml");
    let binary = dir.path().join("matmul.elf");
    std::fs::write(&binary, b"\x7fELF").unwrap();
    let params = dir.path().join("params.bin");
    std::fs::write(&params, b"\x01\x02").unwrap();

    let server = MockServer::start();
    let expected = envelope(
        &proto::RegisterFunction {
            name: "matmul".into(),
            context_size: 64 << 20,
            engine_type: "Kvm".into(),
            executable: Some(proto::register_function::Executable::BinaryLength(4)),
            input_sets: vec![
                proto::RegistrationSet {
                    identifier: "matrices".into(),
                    set: None,
                },
                proto::RegistrationSet {
                    identifier: "config".into(),
                    set: Some(proto::DataSet {
                        items: vec![data_item("params", 3, 2)],
                    }),
                },
            ],
            output_sets: vec!["result".into()],
            min_set_bytes: vec![4096],
        },
        b"\x7fELF\x01\x02",
    );
    let m = expect_body(
        &server,
        "/register/function",
        expected,
        200,
        status("Function registered"),
    );

    let static_arg = format!("config:params#3=@{}", params.display());
    let out = run(
        &cfg,
        &[
            "--url",
            &server.base_url(),
            "function",
            "register",
            binary.to_str().unwrap(),
            "--engine",
            "kvm",
            "--context-size",
            "64M",
            "--input-set",
            "matrices",
            "--input-set",
            "config",
            "--static",
            &static_arg,
            "--output-set",
            "result",
            "--min-set-bytes",
            "4096",
        ],
    );
    assert!(out.status.success(), "stderr: {}", stderr(&out));
    m.assert();
    assert_eq!(stdout(&out).trim(), "Function registered");
}

#[test]
fn register_composition_from_stdin() {
    let dir = tempfile::tempdir().unwrap();
    let cfg = dir.path().join("config.toml");
    let server = MockServer::start();
    let text = "composition C (in) => (out) {}\n";
    let expected = envelope(
        &proto::RegisterComposition {
            composition: text.into(),
            input_sets: vec![],
        },
        b"",
    );
    let m = expect_body(
        &server,
        "/register/composition",
        expected,
        200,
        status("Function registered"),
    );
    let out = run_with_stdin(
        &cfg,
        &["--url", &server.base_url(), "composition", "register", "-"],
        Some(text),
    );
    assert!(out.status.success(), "stderr: {}", stderr(&out));
    m.assert();
}

#[test]
fn composition_check_works_offline() {
    let dir = tempfile::tempdir().unwrap();
    let cfg = dir.path().join("config.toml");
    let file = dir.path().join("c.comp");
    std::fs::write(
        &file,
        "function F (a) => (b);\ncomposition C (x) => (y) {\n    F (a = all x) => (y = b);\n}\n",
    )
    .unwrap();
    // No server is involved; an unreachable URL proves it.
    let out = run(
        &cfg,
        &[
            "--url",
            "http://127.0.0.1:9",
            "composition",
            "check",
            file.to_str().unwrap(),
        ],
    );
    assert!(out.status.success(), "stderr: {}", stderr(&out));
    assert_eq!(
        stdout(&out),
        "composition C parsed (1 function applications)\n"
    );

    let out = run_with_stdin(
        &cfg,
        &["composition", "check"],
        Some("composition C (x) => (y) {"),
    );
    assert_eq!(out.status.code(), Some(1));
    let err = stderr(&out);
    assert!(err.contains("composition:"), "stderr: {err}");
    assert!(!err.starts_with("error: "), "stderr: {err}");
}

fn sample_response() -> Vec<u8> {
    envelope(
        &proto::DandelionResponse {
            sets: vec![proto::DataSet {
                items: vec![data_item("msg", 0, 11), data_item("blob", 7, 3)],
            }],
            trace: Some("{\"start\":10,\"end\":42}".into()),
        },
        b"hello world\x00\xff\x01",
    )
}

#[test]
fn invoke_by_name_with_inputs() {
    let dir = tempfile::tempdir().unwrap();
    let cfg = dir.path().join("config.toml");
    let f = dir.path().join("a.bin");
    std::fs::write(&f, b"AAA").unwrap();

    let server = MockServer::start();
    let expected = envelope(
        &proto::DandelionRequest {
            target: Some(proto::dandelion_request::Target::Name("matmul".into())),
            sets: vec![
                proto::DataSet {
                    items: vec![data_item("a", 0, 3), data_item("b", 5, 3)],
                },
                proto::DataSet {
                    items: vec![data_item("c", 0, 1)],
                },
            ],
        },
        b"AAAlitx",
    );
    let m = expect_body(&server, "/hot/matmul", expected, 200, sample_response());
    let a = format!("m:a=@{}", f.display());
    let out = run(
        &cfg,
        &[
            "--url",
            &server.base_url(),
            "invoke",
            "matmul",
            "--input",
            &a,
            "--input",
            "cfg:c=x",
            "--input",
            "m:b#5=lit",
        ],
    );
    assert!(out.status.success(), "stderr: {}", stderr(&out));
    m.assert();
    let s = stdout(&out);
    assert!(s.contains("set 0: 2 items"), "{s}");
    assert!(s.contains("| hello world"), "{s}");
    assert!(s.contains("\"blob\"  key=7  size=3 B"), "{s}");
    assert!(s.contains("trace:"), "{s}");
    assert!(s.contains("\"end\": 42"), "{s}");
}

#[test]
fn exit_codes() {
    let dir = tempfile::tempdir().unwrap();
    let cfg = dir.path().join("config.toml");
    for (code_status, message, code) in [
        (400, "Failed to serve request: no such function", 3),
        (500, "Failed to serve request: boom", 4),
        (503, "Server is shutting down", 5),
    ] {
        let server = MockServer::start();
        server.mock(|when, then| {
            when.method(POST).path("/hot/matmul");
            then.status(code_status).body(status(message));
        });
        let out = run(&cfg, &["--url", &server.base_url(), "invoke", "nope"]);
        assert_eq!(out.status.code(), Some(code), "status {code_status}");
        assert!(
            stderr(&out).contains(&format!("error: {message} (HTTP {code_status})")),
            "stderr: {}",
            stderr(&out)
        );
    }

    // Port 9 (discard) on localhost is essentially never listening.
    let out = run(&cfg, &["--url", "http://127.0.0.1:9", "ping"]);
    assert_eq!(out.status.code(), Some(2), "stderr: {}", stderr(&out));
    let out = run(&cfg, &["invoke", "f", "--input", "bad"]);
    assert_eq!(out.status.code(), Some(1));
}

#[test]
fn ping_checks_the_protocol() {
    let dir = tempfile::tempdir().unwrap();
    let cfg = dir.path().join("config.toml");
    let server = MockServer::start();
    let m = server.mock(|when, then| {
        when.method(GET).path("/");
        then.status(200).body(status("Hello, World\n"));
    });
    let out = run(&cfg, &["--url", &server.base_url(), "ping", "-v"]);
    assert!(out.status.success(), "stderr: {}", stderr(&out));
    m.assert();
    assert!(stdout(&out).contains("200 OK"));
    assert!(stdout(&out).contains("protocol v1"));
    assert!(
        stderr(&out).contains("GET "),
        "verbose output: {}",
        stderr(&out)
    );
}

#[test]
fn config_commands() {
    let dir = tempfile::tempdir().unwrap();
    let cfg = dir.path().join("sub/config.toml");

    let out = run(&cfg, &["config", "path"]);
    assert_eq!(stdout(&out).trim(), cfg.to_str().unwrap());

    assert!(run(&cfg, &["config", "set", "url", "http://h:8080"])
        .status
        .success());
    assert!(run(&cfg, &["config", "set", "engine", "kvm"])
        .status
        .success());
    assert!(
        run(&cfg, &["config", "set", "engine", "wasm"])
            .status
            .code()
            == Some(1)
    );

    assert_eq!(
        stdout(&run(&cfg, &["config", "get", "engine"])).trim(),
        "Kvm"
    );
    assert_eq!(
        stdout(&run(&cfg, &["config", "get", "hot_path"])).trim(),
        "/hot/matmul"
    );
    assert_eq!(
        run(&cfg, &["config", "get", "timeout"]).status.code(),
        Some(1)
    );
    assert_eq!(
        stdout(&run(&cfg, &["config", "get"])),
        "url = http://h:8080\nengine = Kvm\n"
    );

    assert!(run(&cfg, &["config", "unset", "url"]).status.success());
    assert_eq!(
        stdout(&run(&cfg, &["config", "get", "url"])).trim(),
        "http://localhost:8080"
    );
    assert_eq!(std::fs::read_to_string(&cfg).unwrap(), "engine = \"Kvm\"\n");
}

