#[test]
fn trace_timestamps() {
    let dir = tempfile::tempdir().unwrap();
    let cfg = dir.path().join("config.toml");
    let server = MockServer::start();
    let m = server.mock(|when, then| {
        when.method(GET).path("/trace/timestamps");
        then.status(200)
            .body(status("[\"DeserializationEnd\",\"EnterDispatcher\"]"));
    });
    let out = run(&cfg, &["--url", &server.base_url(), "trace", "timestamps"]);
    assert!(out.status.success(), "stderr: {}", stderr(&out));
    assert_eq!(stdout(&out), "0  DeserializationEnd\n1  EnterDispatcher\n");

    let out = run(
        &cfg,
        &["--url", &server.base_url(), "trace", "timestamps", "--json"],
    );
    assert!(out.status.success(), "stderr: {}", stderr(&out));
    assert_eq!(
        stdout(&out),
        "[\"DeserializationEnd\",\"EnterDispatcher\"]\n"
    );
    m.assert_calls(2);
}
